#!/usr/bin/env python3
"""
Generates exact integer substitution tables for the Spectre Tile(1,1) tiling.

Every vertex of every spectre in the substitution system lies on the rank-4
Z-module spanned by  e0=(1,0), e1=(s3/2,1/2), e2=(1/2,s3/2), e3=(0,1)
(unit vectors at 0/30/60/90 degrees; e4..e11 are integer combinations).
All substitution transforms are elements of the group generated by
30-degree rotations, the y-axis mirror, and module translations, so the
whole hierarchy can be computed EXACTLY in integers.

Outputs:
  tables.h / tables.rs : per-level child transforms, rules, AABBs, geometry
  ref_leaves.json      : reference leaf transforms (float) for validation
  spectre_sample.svg   : visual sanity check
"""
import json, math

SQ3 = math.sqrt(3.0)
LABELS = ["Gamma", "Delta", "Theta", "Lambda", "Xi", "Pi", "Sigma", "Phi", "Psi"]
LIDX = {n: i for i, n in enumerate(LABELS)}
RULES = {
    "Gamma":  ["Pi", "Delta", None, "Theta", "Sigma", "Xi", "Phi", "Gamma"],
    "Delta":  ["Xi", "Delta", "Xi", "Phi", "Sigma", "Pi", "Phi", "Gamma"],
    "Theta":  ["Psi", "Delta", "Pi", "Phi", "Sigma", "Pi", "Phi", "Gamma"],
    "Lambda": ["Psi", "Delta", "Xi", "Phi", "Sigma", "Pi", "Phi", "Gamma"],
    "Xi":     ["Psi", "Delta", "Pi", "Phi", "Sigma", "Psi", "Phi", "Gamma"],
    "Pi":     ["Psi", "Delta", "Xi", "Phi", "Sigma", "Psi", "Phi", "Gamma"],
    "Sigma":  ["Xi", "Delta", "Xi", "Phi", "Sigma", "Pi", "Lambda", "Gamma"],
    "Phi":    ["Psi", "Delta", "Psi", "Phi", "Sigma", "Pi", "Phi", "Gamma"],
    "Psi":    ["Psi", "Delta", "Psi", "Phi", "Sigma", "Psi", "Phi", "Gamma"],
}
MAX_LEVEL = 32

# ---------------------------------------------------------------- module math
def madd(a, b): return tuple(x + y for x, y in zip(a, b))
def mneg(a):    return tuple(-x for x in a)

def rot30(v):
    """rotate module vector by +30 deg: e_k -> e_{k+1}; e4 = e2 - e0."""
    u0, u1, u2, u3 = v
    return (-u3, u0, u1 + u3, u2)

def mirror_y(v):
    """mirror across y-axis (x -> -x): e_k -> e_{6-k}."""
    u0, u1, u2, u3 = v
    return (-u0 - u2, -u1, u2, u1 + u3)

def apply_sr(s, r, v):
    if s: v = mirror_y(v)
    for _ in range(r % 12): v = rot30(v)
    return v

def to_xy(v):
    u0, u1, u2, u3 = v
    return (u0 + SQ3 / 2 * u1 + 0.5 * u2, 0.5 * u1 + SQ3 / 2 * u2 + u3)

# group element g = (s, r, t): P -> t + Rot(30r) * MirrorY^s * P
ID = (0, 0, (0, 0, 0, 0))
def g_apply(g, p):
    s, r, t = g
    return madd(t, apply_sr(s, r, p))
def g_compose(g1, g2):
    s1, r1, t1 = g1
    s2, r2, t2 = g2
    s = s1 ^ s2
    r = (r1 + (r2 if s1 == 0 else -r2)) % 12
    t = madd(t1, apply_sr(s1, r1, t2))
    return (s, r, t)
def g_rot(deg):   return (0, (deg // 30) % 12, (0, 0, 0, 0))
def g_trans(t):   return (0, 0, t)
MIRROR = (1, 0, (0, 0, 0, 0))

# --------------------------------------------------------- spectre geometry
# unit edge directions of the Tile(1,1) boundary, in 30-degree units
EDGE_DIRS = [0, 10, 1, 3, 0, 2, 5, 7, 4, 6, 6, 8, 11, 9]
E = [apply_sr(0, k, (1, 0, 0, 0)) for k in range(12)]
SPECTRE_PTS = [(0, 0, 0, 0)]
for d in EDGE_DIRS[:-1]:
    SPECTRE_PTS.append(madd(SPECTRE_PTS[-1], E[d]))
assert madd(SPECTRE_PTS[-1], E[EDGE_DIRS[-1]]) == (0, 0, 0, 0), "polygon must close"

# cross-check against the reference float coordinates
REF_PTS = [(0,0),(1,0),(1.5,-SQ3/2),(1.5+SQ3/2,0.5-SQ3/2),(1.5+SQ3/2,1.5-SQ3/2),
           (2.5+SQ3/2,1.5-SQ3/2),(3+SQ3/2,1.5),(3.0,2.0),(3-SQ3/2,1.5),
           (2.5-SQ3/2,1.5+SQ3/2),(1.5-SQ3/2,1.5+SQ3/2),(0.5-SQ3/2,1.5+SQ3/2),
           (-SQ3/2,1.5),(0.0,1.0)]
for mp, fp in zip(SPECTRE_PTS, REF_PTS):
    x, y = to_xy(mp)
    assert abs(x - fp[0]) < 1e-12 and abs(y - fp[1]) < 1e-12, (mp, fp)

QUAD0 = [SPECTRE_PTS[3], SPECTRE_PTS[5], SPECTRE_PTS[7], SPECTRE_PTS[11]]
GAMMA2 = (0, 1, SPECTRE_PTS[8])   # second mystic tile: translate(p8) o rot(30)

# ------------------------------------------------- per-level child transforms
TRANSFORMATION_RULES = [[60, 3, 1], [0, 2, 0], [60, 3, 1], [60, 3, 1],
                        [0, 2, 0], [60, 3, 1], [-120, 3, 3]]

def build_level_transforms(quad):
    """Exact port of the reference buildSupertiles() transform derivation."""
    transformations = [ID]
    total_angle = 0
    rotation = ID
    transformed_quad = list(quad)
    for ang, _from, _to in TRANSFORMATION_RULES:
        if ang != 0:
            total_angle += ang
            rotation = g_rot(total_angle)
            transformed_quad = [g_apply(rotation, q) for q in quad]
        ttt = g_trans(madd(g_apply(transformations[-1], quad[_from]),
                           mneg(transformed_quad[_to])))
        transformations.append(g_compose(ttt, rotation))
    transformations = [g_compose(MIRROR, t) for t in transformations]
    super_quad = [g_apply(transformations[6], quad[2]),
                  g_apply(transformations[5], quad[1]),
                  g_apply(transformations[3], quad[2]),
                  g_apply(transformations[0], quad[1])]
    return transformations, super_quad

CHILD = [None]  # CHILD[l][i] maps a level-(l-1) child frame into level-l frame
quad = QUAD0
for lvl in range(1, MAX_LEVEL + 1):
    tf, quad = build_level_transforms(quad)
    assert all(t[0] == 1 for t in tf), "children carry exactly one mirror"
    CHILD.append(tf)

# ---------------------------------------------------------------- validation
# Float port of the reference algorithm (verbatim math), compared against the
# exact system by expanding to leaves.
def f_mul(A, B):
    return [A[0]*B[0]+A[1]*B[3], A[0]*B[1]+A[1]*B[4], A[0]*B[2]+A[1]*B[5]+A[2],
            A[3]*B[0]+A[4]*B[3], A[3]*B[1]+A[4]*B[4], A[3]*B[2]+A[4]*B[5]+A[5]]
def f_rot(a): c, s = math.cos(a), math.sin(a); return [c, -s, 0, s, c, 0]
F_ID = [1, 0, 0, 0, 1, 0]
def f_of_g(g):
    s, r, t = g
    m = f_mul(f_rot(math.radians(30 * r)), [-1, 0, 0, 0, 1, 0] if s else F_ID)
    tx, ty = to_xy(t)
    m[2] += tx; m[5] += ty
    return m

def ref_leaves_float(n_iter, top_label):
    """Reference algorithm, float matrices, returns leaf (label, matrix)."""
    tiles = {lab: [("T", lab, F_ID)] for lab in LABELS if lab != "Gamma"}
    tiles["Gamma"] = [("T", "Gamma1", F_ID),
                      ("T", "Gamma2", f_mul([1,0,REF_PTS[8][0],0,1,REF_PTS[8][1]],
                                            f_rot(math.pi/6)))]
    quad = [REF_PTS[i] for i in (3, 5, 7, 11)]
    for _ in range(n_iter):
        transformations = [F_ID]; total = 0; rot = F_ID; tq = list(quad)
        for ang, fr, to in TRANSFORMATION_RULES:
            if ang:
                total += ang; rot = f_rot(math.radians(total))
                tq = [(rot[0]*p[0]+rot[1]*p[1], rot[3]*p[0]+rot[4]*p[1]) for p in quad]
            last = transformations[-1]
            src = (last[0]*quad[fr][0]+last[1]*quad[fr][1]+last[2],
                   last[3]*quad[fr][0]+last[4]*quad[fr][1]+last[5])
            ttt = [1, 0, src[0]-tq[to][0], 0, 1, src[1]-tq[to][1]]
            transformations.append(f_mul(ttt, rot))
        transformations = [f_mul([-1,0,0,0,1,0], t) for t in transformations]
        def tp(M, p): return (M[0]*p[0]+M[1]*p[1]+M[2], M[3]*p[0]+M[4]*p[1]+M[5])
        nquad = [tp(transformations[6], quad[2]), tp(transformations[5], quad[1]),
                 tp(transformations[3], quad[2]), tp(transformations[0], quad[1])]
        nt = {}
        for lab, subs in RULES.items():
            geo = []
            for sub, tf in zip(subs, transformations):
                if sub is None: continue
                geo += [(k, l, f_mul(tf, m)) for (k, l, m) in tiles[sub]]
            nt[lab] = geo
        tiles = nt; quad = nquad
    return tiles[top_label]

def exact_leaves(n_iter, top_label):
    """Implicit table-driven traversal (the production algorithm)."""
    out = []
    def rec(level, lab, g):
        if level == 0:
            if lab == "Gamma":
                out.append(("Gamma1", g)); out.append(("Gamma2", g_compose(g, GAMMA2)))
            else:
                out.append((lab, g))
            return
        for i, sub in enumerate(RULES[lab]):
            if sub is None: continue
            rec(level - 1, sub, g_compose(g, CHILD[level][i]))
    rec(n_iter, top_label, ID)
    return out

for N in (1, 2, 3):
    for top in ("Delta", "Gamma", "Psi"):
        ref = ref_leaves_float(N, top)
        exa = exact_leaves(N, top)
        assert len(ref) == len(exa), (N, top, len(ref), len(exa))
        for (_, rl, rm), (el, eg) in zip(ref, exa):
            assert rl == el, (rl, el)
            em = f_of_g(eg)
            assert all(abs(a - b) < 1e-6 for a, b in zip(rm, em)), (N, top, rm, em)
print("VALIDATED: exact integer system == reference float algorithm (N=1..3, all leaf transforms)")

# ------------------------------------------------------------------ AABBs
def rect_of_pts(pts):
    xs = [p[0] for p in pts]; ys = [p[1] for p in pts]
    return (min(xs), min(ys), max(xs), max(ys))

def rect_transform(g, rect):
    s, r, t = g
    a = math.radians(30 * r); c, sn = math.cos(a), math.sin(a)
    m00, m01, m10, m11 = c, -sn, sn, c
    if s: m00, m10 = -m00, -m10
    cx, cy = (rect[0]+rect[2])/2, (rect[1]+rect[3])/2
    hx, hy = (rect[2]-rect[0])/2, (rect[3]-rect[1])/2
    ncx = m00*cx + m01*cy; ncy = m10*cx + m11*cy
    nhx = abs(m00)*hx + abs(m01)*hy; nhy = abs(m10)*hx + abs(m11)*hy
    tx, ty = to_xy(t)
    return (ncx-nhx+tx, ncy-nhy+ty, ncx+nhx+tx, ncy+nhy+ty)

def rect_union(a, b):
    return (min(a[0],b[0]), min(a[1],b[1]), max(a[2],b[2]), max(a[3],b[3]))

AABB = [[None]*9 for _ in range(MAX_LEVEL+1)]
base = rect_of_pts([to_xy(p) for p in SPECTRE_PTS])
g2rect = rect_transform(GAMMA2, base)
for li, lab in enumerate(LABELS):
    AABB[0][li] = rect_union(base, g2rect) if lab == "Gamma" else base
for lvl in range(1, MAX_LEVEL+1):
    for li, lab in enumerate(LABELS):
        r = None
        for i, sub in enumerate(RULES[lab]):
            if sub is None: continue
            cr = rect_transform(CHILD[lvl][i], AABB[lvl-1][LIDX[sub]])
            r = cr if r is None else rect_union(r, cr)
        AABB[lvl][li] = r

# tile counts per level (Delta root)
cnt = {lab: (2 if lab == "Gamma" else 1) for lab in LABELS}
counts = [cnt["Delta"]]
for lvl in range(1, MAX_LEVEL+1):
    cnt = {lab: sum(cnt[s] for s in RULES[lab] if s) for lab in RULES}
    counts.append(cnt["Delta"])

# ------------------------------------------------------- triangulation (fan-free)
def ear_clip(poly):
    n = len(poly); idx = list(range(n)); tris = []
    def area2(a, b, c): return (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])
    total = sum(area2(poly[0], poly[i], poly[i+1]) for i in range(1, n-1))
    ccw = total > 0
    guard = 0
    while len(idx) > 3 and guard < 10000:
        guard += 1
        m = len(idx)
        for k in range(m):
            a, b, c = idx[(k-1) % m], idx[k], idx[(k+1) % m]
            ar = area2(poly[a], poly[b], poly[c])
            if (ar > 1e-12) != ccw and abs(ar) > 1e-12: continue
            if abs(ar) < 1e-12: continue
            ok = True
            for j in idx:
                if j in (a, b, c): continue
                p = poly[j]
                d1 = area2(poly[a], poly[b], p); d2 = area2(poly[b], poly[c], p); d3 = area2(poly[c], poly[a], p)
                if ccw:
                    inside = d1 >= -1e-12 and d2 >= -1e-12 and d3 >= -1e-12
                else:
                    inside = d1 <= 1e-12 and d2 <= 1e-12 and d3 <= 1e-12
                if inside: ok = False; break
            if ok:
                tris.append((a, b, c)); idx.pop(k); break
        else:
            raise RuntimeError("ear clipping failed")
    tris.append(tuple(idx))
    return tris

TRIS = ear_clip([to_xy(p) for p in SPECTRE_PTS])
assert len(TRIS) == 12

# ----------------------------------------------------------------- emit files
def emit_c():
    L = []
    L.append("/* AUTO-GENERATED by gen_tables.py - exact spectre substitution tables */")
    L.append("#pragma once\n#include <stdint.h>")
    L.append(f"#define SP_MAX_LEVEL {MAX_LEVEL}")
    L.append("enum { GAMMA=0, DELTA, THETA, LAMBDA, XI, PI_, SIGMA, PHI, PSI };")
    L.append("/* child label per (label, position); 255 = absent (Gamma pos 2) */")
    rows = []
    for lab in LABELS:
        rows.append("{" + ",".join("255" if s is None else str(LIDX[s]) for s in RULES[lab]) + "}")
    L.append("static const uint8_t SP_RULES[9][8] = {" + ",".join(rows) + "};")
    L.append("/* child transforms per level: rotation (30deg units, mirror implied) and module translation */")
    rots = CHILD[1]
    L.append("static const uint8_t SP_CHILD_ROT[SP_MAX_LEVEL+1][8] = { {0},")
    for lvl in range(1, MAX_LEVEL+1):
        L.append("  {" + ",".join(str(t[1]) for t in CHILD[lvl]) + "},")
    L.append("};")
    L.append("static const int64_t SP_CHILD_T[SP_MAX_LEVEL+1][8][4] = { {{0}},")
    for lvl in range(1, MAX_LEVEL+1):
        row = ",".join("{" + ",".join(str(x) for x in t[2]) + "}" for t in CHILD[lvl])
        L.append("  {" + row + "},")
    L.append("};")
    L.append("/* conservative local AABB per (level,label): minx,miny,maxx,maxy */")
    L.append("static const double SP_AABB[SP_MAX_LEVEL+1][9][4] = {")
    for lvl in range(MAX_LEVEL+1):
        row = ",".join("{" + ",".join(f"{v:.17g}" for v in AABB[lvl][li]) + "}" for li in range(9))
        L.append("  {" + row + "},")
    L.append("};")
    L.append("/* spectre vertices in module coords */")
    L.append("static const int32_t SP_VERTS[14][4] = {" +
             ",".join("{" + ",".join(str(x) for x in p) + "}" for p in SPECTRE_PTS) + "};")
    g2s, g2r, g2t = GAMMA2
    L.append(f"static const uint8_t SP_GAMMA2_ROT = {g2r};")
    L.append("static const int64_t SP_GAMMA2_T[4] = {" + ",".join(str(x) for x in g2t) + "};")
    L.append("static const uint16_t SP_TRIS[12][3] = {" +
             ",".join("{%d,%d,%d}" % t for t in TRIS) + "};")
    open("/home/claude/spectre/tables.h", "w").write("\n".join(L) + "\n")

def emit_rust():
    L = []
    L.append("// AUTO-GENERATED by gen_tables.py - exact spectre substitution tables")
    L.append(f"pub const MAX_LEVEL: usize = {MAX_LEVEL};")
    L.append("/// child label per (label, position); 255 = absent (Gamma pos 2)")
    rows = ",".join("[" + ",".join("255" if s is None else str(LIDX[s]) for s in RULES[lab]) + "]" for lab in LABELS)
    L.append(f"pub const RULES: [[u8; 8]; 9] = [{rows}];")
    L.append("/// child rotation (30 deg units; every child also carries one y-mirror)")
    rows = ",".join("[" + ",".join(str(t[1]) for t in CHILD[l]) + "]" for l in range(1, MAX_LEVEL+1))
    L.append(f"pub const CHILD_ROT: [[u8; 8]; {MAX_LEVEL}] = [{rows}];")
    L.append("/// child translation in module coords, per level (index 0 = level 1)")
    rows = ",".join("[" + ",".join("[" + ",".join(str(x) for x in t[2]) + "]" for t in CHILD[l]) + "]" for l in range(1, MAX_LEVEL+1))
    L.append(f"pub const CHILD_T: [[[i64; 4]; 8]; {MAX_LEVEL}] = [{rows}];")
    L.append("/// conservative local AABB per (level,label): [minx,miny,maxx,maxy]")
    rows = ",".join("[" + ",".join("[" + ",".join(f"{v:.17}" for v in AABB[l][li]) + "]" for li in range(9)) + "]" for l in range(MAX_LEVEL+1))
    L.append(f"pub const LOCAL_AABB: [[[f64; 4]; 9]; {MAX_LEVEL+1}] = [{rows}];")
    rows = ",".join("[" + ",".join(str(x) for x in p) + "]" for p in SPECTRE_PTS)
    L.append(f"pub const SPECTRE_VERTS: [[i32; 4]; 14] = [{rows}];")
    L.append(f"pub const GAMMA2_ROT: u8 = {GAMMA2[1]};")
    L.append("pub const GAMMA2_T: [i64; 4] = [" + ",".join(str(x) for x in GAMMA2[2]) + "];")
    L.append("pub const TRIANGLES: [[u16; 3]; 12] = [" + ",".join("[%d,%d,%d]" % t for t in TRIS) + "];")
    counts_s = ",".join(str(c) for c in counts[:21])
    L.append(f"/// Delta-root tile counts for levels 0..20\npub const TILE_COUNTS: [u128; 21] = [{counts_s}];")
    open("/home/claude/spectre/rust/spectre-core/src/tables.rs", "w").write("\n".join(L) + "\n")

def emit_ref_json():
    data = []
    for lab, g in exact_leaves(3, "Delta"):
        s, r, t = g
        x, y = to_xy(t)
        data.append({"label": lab, "s": s, "r": r, "x": x, "y": y})
    json.dump(data, open("/home/claude/spectre/ref_leaves_n3_delta.json", "w"))

def emit_svg():
    leaves = exact_leaves(3, "Delta")
    pal = {"Gamma1": "#c4c9a9", "Gamma2": "#9ca074", "Delta": "#f0f0f0", "Theta": "#ffbfbf",
           "Lambda": "#ffa07a", "Xi": "#fff200", "Pi": "#87cefa", "Sigma": "#f5f5dc",
           "Phi": "#00ff00", "Psi": "#00ffff"}
    polys = []
    allx, ally = [], []
    for lab, g in leaves:
        pts = [to_xy(g_apply(g, p)) for p in SPECTRE_PTS]
        allx += [p[0] for p in pts]; ally += [p[1] for p in pts]
        d = " ".join(f"{x:.3f},{y:.3f}" for x, y in pts)
        polys.append(f'<polygon points="{d}" fill="{pal[lab]}" stroke="black" stroke-width="0.08"/>')
    x0, y0, x1, y1 = min(allx)-1, min(ally)-1, max(allx)+1, max(ally)+1
    svg = (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{x0} {y0} {x1-x0} {y1-y0}" '
           f'width="900" height="900">' + "".join(polys) + "</svg>")
    open("/mnt/user-data/outputs/spectre_sample.svg", "w").write(svg)
    print(f"SVG: {len(leaves)} tiles")

import os
os.makedirs("/home/claude/spectre/rust/spectre-core/src", exist_ok=True)
emit_c(); emit_rust(); emit_ref_json(); emit_svg()
scale = (AABB[8][1][2]-AABB[8][1][0]) / (AABB[7][1][2]-AABB[7][1][0])
print(f"tables emitted. linear inflation/level ~ {scale:.4f}")
print(f"tiles at level 10 (Delta root): {counts[10]:,}; level 20: {counts[20]:,}")
print(f"max |translation| component at level {MAX_LEVEL}: "
      f"{max(abs(x) for t in CHILD[MAX_LEVEL] for x in t[2]):,}")
